css:
section.go-SurveyBanner,
section[aria-label$="Go Developer Survey"],
.Cookie-notice {
  display: none !important;
}

js:
// A cookie notice by another name: only elements whose class, id, role or
// label says notice, banner, cookie or consent, not every box on the page.
// morse.watch looks at new elements only, once a frame.
const NOTICE = '[class*="cookie" i], [id*="cookie" i], [class*="consent" i], [id*="consent" i], [aria-label*="cookie" i], [class*="notice" i], [class*="banner" i], [role="dialog"], [role="alertdialog"]';
morse.watch(NOTICE, el => {
  const text = el.textContent || "";
  if (text.length > 500 || !/cookie/i.test(text)) return;
  const pos = getComputedStyle(el).position;
  if (pos !== "fixed" && pos !== "sticky") return;
  el.style.setProperty("display", "none", "important");
});
